// GGJ weekly editorial calendar — rotates through three categories.
// Jam Stories are deliberately NOT here: those stay with the community.
const calendar = {
  methods: [
    'how to facilitate the Understand sprint of a Global Goals Jam',
    'problem framing for SDG design sprints: how might we questions that work',
    'rapid prototyping techniques for a 2-day SDG jam',
    'how to run a stakeholder mapping session for a local SDG challenge',
    'pitch formats for SDG jam teams: three minutes, one prototype',
    'facilitation methods for mixed groups of students, civil servants and designers',
    'how to keep energy up during a 48-hour design sprint',
    'from prototype to pilot: the Implement sprint explained',
    'systems thinking methods for local SDG action',
    'how to choose the right SDG target for your city jam',
  ],
  impact: [
    'what happens after a design sprint: how local SDG prototypes become projects',
    'measuring the impact of community design sprints for the SDGs',
    'how cities use design jams to accelerate local SDG action',
    'examples of student-led SDG innovation projects that scaled',
    'the role of universities in local SDG implementation',
    'how municipalities partner with design communities on the Global Goals',
  ],
  news: [
    'latest news on UN Sustainable Development Goals progress 2026',
    'SDG Action Week 2026 events and initiatives',
    'climate resilience design innovation news',
    'youth-led climate and SDG initiatives worldwide news',
    'urban resilience and adaptation projects news',
    'circular economy local initiatives news',
  ],
};

// One article per week: the ISO week number picks category + topic, so the
// schedule rotates predictably and never repeats within ~a quarter.
const now = new Date();
const jan1 = new Date(now.getFullYear(), 0, 1);
const week = Math.floor((now - jan1) / (7 * 24 * 3600 * 1000));
const cats = Object.keys(calendar);
const category = cats[week % cats.length];
const topics = calendar[category];
const topic = topics[Math.floor(week / cats.length) % topics.length];

const searchQuery = category === 'news'
  ? `${topic} ${now.getFullYear()}`
  : `${topic} ${category === 'impact' ? 'case study' : 'facilitation method'}`;

return [{ json: { category, topic, searchQuery, week } }];

const res = $input.first().json;
const results = (res.results || []).filter(r => r.url && r.content && r.content.length > 300);
const urls = results.slice(0, 4).map(r => r.url);
const prev = $('Select Content Theme').first().json;
return [{ json: { ...prev, urls, sources: results.slice(0, 4).map(r => ({ title: r.title, url: r.url })) } }];

const r = $input.first().json;
const prev = $('Pick Image Query').first().json;
const photos = (r.results || []).filter(p => p.width > p.height);
// Rotate within the result set too, so the same query still yields different covers over time.
const pick = photos.length ? photos[prev.week % photos.length] : (r.results || [])[0];
const headerImageUrl = pick ? `${pick.urls.raw}&w=1600&h=900&fit=crop&q=80` : null;
const imageCredit = pick ? `Photo by ${pick.user.name} on Unsplash` : null;
return [{ json: { ...prev, headerImageUrl, imageCredit } }];

const gen = $('Generate Article (Supabase Edge)').first().json;
const img = $('Select Best Image').first().json;
const a = gen.article || gen;
if (!a || !a.title) throw new Error('generate-article returned no article: ' + JSON.stringify(gen).slice(0, 300));

const slug = (a.slug || a.title).toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').substring(0, 80);
const words = (a.content_markdown || '').split(/\s+/).length;
const readMinutes = Math.max(1, Math.ceil(words / 200));
const articleUrl = `https://www.globalgoalsjam.org/articles/${slug}`;

// Only the three editorial categories are allowed to be automated.
const allowed = ['methods', 'impact', 'news'];
const category = allowed.includes(a.suggested_category) ? a.suggested_category : img.category;

let linkedInPost = (a.linkedin_post || '').replace(/\{\{\s*article_url\s*\}\}/g, articleUrl);
if (!linkedInPost.includes(articleUrl)) linkedInPost = `${linkedInPost.trim()}\n\n${articleUrl}`;
if (!linkedInPost.trim()) {
  const tags = (a.tags || []).slice(0, 3).map(t => '#' + String(t).replace(/\s+/g, ''));
  linkedInPost = `${a.excerpt}\n\n${articleUrl}\n\n${tags.join(' ')} #GlobalGoalsJam #SDGs`;
}

const sourcesNote = (img.sources || []).length
  ? `\n\n---\n*Sources: ${img.sources.map(s => `[${s.title || s.url}](${s.url})`).join(' · ')}*`
  : '';

return [{ json: {
  article: {
    slug,
    title: a.title,
    excerpt: a.excerpt,
    content: (a.content_markdown || '') + sourcesNote,
    cover_image_url: img.headerImageUrl,
    cover_caption: img.imageCredit,
    category,
    tags: (a.tags || []).join(', '),
    author_name: 'Global Goals Jam',
    source: 'ai',
    status: 'published',
    read_minutes: readMinutes,
    published_at: new Date().toISOString(),
    linkedin_post: linkedInPost,
  },
  linkedInPost,
  articleUrl,
}}];

// Cover photo search terms — always SDG / jam / hackathon flavoured, rotating so
// consecutive articles don't reuse the same kind of image.
const prev = $input.first().json;
const pools = {
  methods: [
    'design sprint workshop sticky notes team',
    'hackathon teamwork whiteboard',
    'facilitator workshop diverse group collaboration',
    'prototyping cardboard workshop hands',
    'brainstorm post-it wall creative team',
  ],
  impact: [
    'community garden city volunteers',
    'sustainable city green rooftop',
    'students presenting project community',
    'urban neighbourhood people collaboration',
    'climate action community project',
  ],
  news: [
    'sustainable development goals city',
    'renewable energy community',
    'climate resilience city flood adaptation',
    'circular economy recycling community',
    'clean water sustainable community',
  ],
};
const pool = pools[prev.category] || pools.methods;
const imageQuery = pool[prev.week % pool.length];
return [{ json: { ...prev, imageQuery } }];
